} from '../utils/aws/cloudwatchUsage.js';
import { CreateUsageDto } from './dto/create-usage.dto.js';
import { UsageDocument } from './dto/read-usage.dto.js';

const { usageData } = SupportedResources;

/** What a dimension's aggregation method makes of a set of readings. */
const reduceSamples = (values: number[], method: aggregationMethod): number => {
    if (values.length === 0) {
        return 0;
    }
    switch (method) {
        case aggregationMethod.max:
            return Math.max(...values);
        case aggregationMethod.min:
            return Math.min(...values);
        case aggregationMethod.average:
            return values.reduce((total, value) => total + value, 0) / values.length;
        case aggregationMethod.count:
            return values.length;
        case aggregationMethod.last:
            return values[values.length - 1];
        default:
            return values.reduce((total, value) => total + value, 0);
    }
};

const ONE_HOUR_IN_MS = 36e5;

/** One clock aligned step of a window, already clamped to the window itself. */
export type UsageStep = { startTime: Date; endTime: Date };

/** One dimension's readings for one window, broken up the way they are priced. */
type UsageCurve = { metadataGroup?: Record<string, string>; usage: UsageResponseDocument[] };

/** The clock edge the step holding an instant opens on. */
const stepEdgeOf = (instant: Date, interval: aggregationInterval): Date => {
    switch (interval) {
        case aggregationInterval.month:
            return new Date(Date.UTC(instant.getUTCFullYear(), instant.getUTCMonth(), 1));
        case aggregationInterval.day:
            return new Date(Date.UTC(instant.getUTCFullYear(), instant.getUTCMonth(), instant.getUTCDate()));
        default:
            return new Date(
                Date.UTC(instant.getUTCFullYear(), instant.getUTCMonth(), instant.getUTCDate(), instant.getUTCHours()),
            );
    }
};

/** The clock edge the step after the one opening on the given edge opens on. */
const nextStepEdge = (edge: Date, interval: aggregationInterval): Date => {
    switch (interval) {
        case aggregationInterval.month:
            return new Date(Date.UTC(edge.getUTCFullYear(), edge.getUTCMonth() + 1, 1));
        case aggregationInterval.day:
            return new Date(Date.UTC(edge.getUTCFullYear(), edge.getUTCMonth(), edge.getUTCDate() + 1));
        default:
            return new Date(edge.getTime() + ONE_HOUR_IN_MS);
    }
};

/**
 * The steps of the requested size a window breaks into. The edges sit on the
 * clock, so a window that opens or closes part way through a step hands back a
 * first and a last step clamped to the window rather than one reaching outside
 * of it.
 */
export const usageStepsOfWindow = (startTime: Date, endTime: Date, interval: aggregationInterval): UsageStep[] => {
    const opens = startTime.getTime();
    const closes = endTime.getTime();
    const steps: UsageStep[] = [];
    if (!(closes > opens)) {
        return steps;
    }
    let edge = stepEdgeOf(startTime, interval);
    while (edge.getTime() < closes) {
        const next = nextStepEdge(edge, interval);
        steps.push({
            startTime: new Date(Math.max(edge.getTime(), opens)),
            endTime: new Date(Math.min(next.getTime(), closes)),
        });
        edge = next;
    }
    return steps;
};

/** Readings ordered the way they happened, oldest first. */
const oldestFirst = (samples: UsageSample[]): UsageSample[] =>
    [...samples].sort((left, right) => new Date(left.timestamp).getTime() - new Date(right.timestamp).getTime());

/** The readings of a set of series inside a window, oldest first. */
const readingsInWindow = async ({
    series,
    startTime,
    endTime,
}: {
    series: UsageSeries[];
    startTime: Date;
    endTime: Date;
}): Promise<UsageSample[]> => {
    const readings: UsageSample[] = [];
    for (const published of series) {
        const samples = await readUsageSamples({ series: published, startTime, endTime });
        samples.forEach((sample) => {
            const at = new Date(sample.timestamp).getTime();
            if (at >= startTime.getTime() && at < endTime.getTime()) {
                readings.push(sample);
            }
        });
    }
    return oldestFirst(readings);
};

/**
 * The curve one set of series draws over a window. Every step of the window is
 * reported, whether or not a reading landed in it: a standing level is carried
 * through the steps that hold no new reading, anything else reads as unused.
 */
const curveOfSeries = async ({
    series,
    steps,
    startTime,
    endTime,
    method,
    carriesStandingLevel,
    metadataGroup,
}: {
    series: UsageSeries[];
    steps: UsageStep[];
    startTime: Date;
    endTime: Date;
    method: aggregationMethod;
    carriesStandingLevel: boolean;
    metadataGroup?: Record<string, string>;
}): Promise<UsageCurve> => {
    // A standing level may have been set however long before the window opened, so a dimension that
    // holds its level is read from the very beginning and the readings ahead of the window only seed it.
    const readFrom = carriesStandingLevel ? new Date(0) : startTime;
    const readings = series.length ? await readingsInWindow({ series, startTime: readFrom, endTime }) : [];
    const opensAt = startTime.getTime();
    let standingLevel: number | undefined;
    while (readings.length && new Date(readings[0].timestamp).getTime() < opensAt) {
        standingLevel = readings.shift().value;
    }
    if (!carriesStandingLevel) {
        standingLevel = undefined;
    }
    // The readings are already in order, so each step takes the ones it holds by walking them once.
    let walked = 0;
    const usage = steps.map((step) => {
        const closes = step.endTime.getTime();
        const inStep: UsageSample[] = [];
        while (walked < readings.length && new Date(readings[walked].timestamp).getTime() < closes) {
            inStep.push(readings[walked]);
            walked += 1;
        }
        let value: number;
        if (inStep.length) {
            value = reduceSamples(
                inStep.map(({ value: reading }) => reading),
                method,
            );
            standingLevel = inStep[inStep.length - 1].value;
        } else if (carriesStandingLevel && standingLevel !== undefined) {
            value = standingLevel;
        } else {
            value = 0;
        }
        return new UsageDocument({
            value: value.toString(),
            startTime: step.startTime.toISOString(),
            endTime: step.endTime.toISOString(),
        }) as UsageResponseDocument;
    });
    return metadataGroup && Object.keys(metadataGroup).length ? { metadataGroup, usage } : { usage };
};

/** Whether a dimension's readings hold a level between them instead of being spent. */
const holdsStandingLevel = (dimension: ReadDimensionResponseData): boolean =>
    dimension?.sampleType === SampleType.continious || dimension?.aggregationMethod === aggregationMethod.last;

/** Whether a dimension is priced by the metadata its readings are grouped by. */
const isPricedByMetadata = (dimension: ReadDimensionResponseData): boolean =>
    Boolean(dimension?.tiersGroupByMetadata && dimension?.tiersGroupByMetadata?.length);

/** Whether a dimension handed back one curve per published metadata group. */
const areCurvesGroupedByMetadata = (rows: unknown): rows is UsageCurve[] =>
    Array.isArray(rows) && rows.length > 0 && rows.every((row) => Array.isArray((row as UsageCurve)?.usage));

export class UsageAggregationEvent {
    public customerId: string;
    public offeringDocument: ReadOfferingResponseData;

    /**
     * The unique identifier for the SaaS business
"
}

